//! Both outputs are generated by the real UI recipes, without initializing GPUI.
#[path = "../examples/table-presets.rs"]
mod exporter;
#[test]
fn versioned_table_recipes_match_the_native_inspector() {
    let bytes = exporter::recipes_bytes().expect("headless recipes");
    assert_eq!(
        bytes,
        include_bytes!("../../hub-host/data/table-presets.json")
    );
    assert_eq!(bytes, exporter::recipes_bytes().expect("repeat"));
    let value: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
    assert_eq!(value["recipes"].as_object().unwrap().len(), 2);
    for kind in ["standings", "relative"] {
        assert_eq!(
            value["recipes"][kind].as_object().unwrap().len(),
            vantare_domain::widget_settings::TABLE_SIZES.len()
        );
    }
}
#[test]
fn versioned_preset_writer_oracle_matches_gpui_operations() {
    let bytes = exporter::oracle_bytes().expect("headless oracle");
    assert_eq!(
        bytes,
        include_bytes!("../../hub-host/fixtures/studio-table-preset-golden.json")
    );
    let value: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
    assert_eq!(value["cases"].as_array().unwrap().len(), 18);
}
